begin;

do $$
begin
  if current_user <> 'postgres' then raise exception 'RL-8C1 prestate violation: migration executor must be postgres'; end if;
  if to_regnamespace('investing') is null or to_regnamespace('extensions') is null then raise exception 'RL-8C1 prestate violation: required schemas are missing'; end if;
  if to_regclass('investing.tenant_memberships') is null or to_regclass('investing.research_investigations') is null or to_regclass('investing.research_experiments') is null or to_regclass('investing.run_inputs_scientific_identities') is null or to_regclass('investing.research_results_scientific_identities') is null or to_regclass('investing.research_evidence_objects_scientific_identities') is null or to_regclass('investing.research_validation_protocols_scientific_identities') is null or to_regclass('investing.research_validation_results_scientific_identities') is null or to_regclass('investing.research_validation_assessment_protocols_scientific_identities') is null or to_regclass('investing.research_validation_assessment_results_scientific_identities') is null or to_regclass('investing.research_experiment_comparison_protocols_scientific_identities') is null or to_regclass('investing.research_experiment_comparison_results_scientific_identities') is null then raise exception 'RL-8C1 prestate violation: accepted post-Genesis predecessor surface is incomplete'; end if;
end $$;

do $$
declare v_role record;
begin
  select * into v_role from pg_catalog.pg_roles where rolname = 'investing_rl8_writer';
  if not found then
    create role investing_rl8_writer nologin noinherit nosuperuser nocreatedb nocreaterole noreplication nobypassrls;
  elsif v_role.rolcanlogin or v_role.rolinherit or v_role.rolsuper or v_role.rolcreatedb or v_role.rolcreaterole or v_role.rolreplication or v_role.rolbypassrls then
    raise exception 'RL-8C1 prestate violation: investing_rl8_writer exists with incompatible attributes';
  end if;
  if pg_catalog.pg_has_role('investing_app', 'investing_rl8_writer', 'member') then raise exception 'RL-8C1 prestate violation: investing_app must not be a member of investing_rl8_writer'; end if;
  if pg_catalog.pg_has_role('service_role', 'investing_rl8_writer', 'member') then raise exception 'RL-8C1 prestate violation: service_role must not be a member of investing_rl8_writer'; end if;
  if pg_catalog.pg_has_role('investing_rl8_writer', 'investing_owner', 'member') then raise exception 'RL-8C1 prestate violation: investing_rl8_writer must not inherit investing_owner'; end if;
end $$;

set local role investing_owner;

