create or replace function investing.rl8c_jsonb_has_number_v1(p_value jsonb) returns boolean language sql immutable strict set search_path = pg_catalog as $$
  select case jsonb_typeof(p_value) when 'number' then true when 'array' then exists (select 1 from pg_catalog.jsonb_array_elements(p_value) as e(value) where investing.rl8c_jsonb_has_number_v1(e.value)) when 'object' then exists (select 1 from pg_catalog.jsonb_each(p_value) as e(key, value) where investing.rl8c_jsonb_has_number_v1(e.value)) else false end
$$;

create or replace function investing.rl8c_canonical_jsonb_v1(p_value jsonb) returns text language plpgsql immutable strict set search_path = pg_catalog as $$
declare v_type text; v_out text;
begin
  v_type := pg_catalog.jsonb_typeof(p_value);
  if v_type = 'null' then return 'null'; elsif v_type = 'boolean' then return lower(p_value::text); elsif v_type = 'number' then raise exception 'RL-8C canonical JSON forbids numbers'; elsif v_type = 'string' then return pg_catalog.to_jsonb(p_value #>> '{}')::text; elsif v_type = 'array' then select '[' || coalesce(pg_catalog.string_agg(investing.rl8c_canonical_jsonb_v1(e.value), ',' order by e.ordinality), '') || ']' into v_out from pg_catalog.jsonb_array_elements(p_value) with ordinality as e(value, ordinality); return v_out; elsif v_type = 'object' then select '{' || coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(e.key)::text || ':' || investing.rl8c_canonical_jsonb_v1(e.value), ',' order by e.key collate "C"), '') || '}' into v_out from pg_catalog.jsonb_each(p_value) as e(key, value); return v_out; end if;
  raise exception 'RL-8C canonical JSON unsupported jsonb type: %', v_type;
end;
$$;

create or replace function investing.rl8c_sha256_hex_v1(p_hash_domain text, p_canonical_payload jsonb) returns text language sql immutable strict set search_path = pg_catalog, extensions as $$
  select upper(pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_hash_domain || E'\n' || investing.rl8c_canonical_jsonb_v1(p_canonical_payload), 'UTF8'), 'sha256'), 'hex'))
$$;

create or replace function investing.reject_research_scientific_promotion_update_delete_v1() returns trigger language plpgsql security invoker set search_path = pg_catalog as $$
begin raise exception 'research scientific promotion identities are append-only'; end;
$$;

revoke all on function investing.rl8c_jsonb_has_number_v1(jsonb) from public, anon, authenticated, service_role;
revoke all on function investing.rl8c_canonical_jsonb_v1(jsonb) from public, anon, authenticated, service_role;
revoke all on function investing.rl8c_sha256_hex_v1(text, jsonb) from public, anon, authenticated, service_role;
revoke all on function investing.reject_research_scientific_promotion_update_delete_v1() from public, anon, authenticated, service_role;

create table investing.research_scientific_promotion_protocols_scientific_identities (
  research_scientific_promotion_protocol_identity_id uuid primary key default gen_random_uuid(),
  operation text not null check (operation = 'RESEARCH_SCIENTIFIC_PROMOTION_PROTOCOL_CREATE_V1'),
  capability text not null check (capability = 'RESEARCH_MUTATE'),
  operation_scope text not null check (operation_scope = 'TENANT_SCOPE'),
  source_context text not null check (source_context = 'PURE_RESEARCH'),
  hash_algorithm text not null check (hash_algorithm = 'SHA-256'),
  hash_domain text not null check (hash_domain = 'SYNTRAKE:SCIENTIFIC_PROMOTION_PROTOCOL:V1'),
  hash_version text not null check (hash_version = 'SYNTRAKE_SHA256_V1'),
  hash_hex text not null check (hash_hex ~ '^[0-9A-F]{64}$'),
  canonical_payload jsonb not null,
  created_at timestamptz not null default transaction_timestamp(),
  constraint research_scientific_promotion_protocols_payload_check check (jsonb_typeof(canonical_payload) = 'object' and not investing.rl8c_jsonb_has_number_v1(canonical_payload) and canonical_payload->>'schemaVersion' = 'SCIENTIFIC_PROMOTION_PROTOCOL_V1' and investing.rl8c_sha256_hex_v1(hash_domain, canonical_payload) = hash_hex),
  constraint research_scientific_promotion_protocols_hash_key unique (hash_algorithm, hash_domain, hash_version, hash_hex),
  constraint research_scientific_promotion_protocols_rl8c_identity_hash_key unique (research_scientific_promotion_protocol_identity_id, hash_hex)
);

create unique index research_scientific_promotion_protocols_protocol_id_key on investing.research_scientific_promotion_protocols_scientific_identities ((canonical_payload->>'protocolId')) where hash_domain = 'SYNTRAKE:SCIENTIFIC_PROMOTION_PROTOCOL:V1';

create table investing.research_scientific_promotion_transitions_scientific_identities (
  research_scientific_promotion_transition_identity_id uuid primary key default gen_random_uuid(),
