  research_scientific_promotion_protocol_identity_id uuid not null, protocol_hash_hex text not null check (protocol_hash_hex ~ '^[0-9A-F]{64}$'),
  subject_experiment_hash_hex text not null check (subject_experiment_hash_hex ~ '^[0-9A-F]{64}$'), subject_experiment_parameters_hash_hex text not null check (subject_experiment_parameters_hash_hex ~ '^[0-9A-F]{64}$'), subject_research_ir_hash_hex text not null check (subject_research_ir_hash_hex ~ '^[0-9A-F]{64}$'),
  predecessor_transition_identity_id uuid, predecessor_transition_hash_hex text check (predecessor_transition_hash_hex is null or predecessor_transition_hash_hex ~ '^[0-9A-F]{64}$'), predecessor_state text not null, resulting_state text not null,
  transition_hash_algorithm text not null check (transition_hash_algorithm = 'SHA-256'), transition_hash_domain text not null check (transition_hash_domain = 'SYNTRAKE:SCIENTIFIC_PROMOTION_TRANSITION:V1'), transition_hash_version text not null check (transition_hash_version = 'SYNTRAKE_SHA256_V1'), transition_hash_hex text not null check (transition_hash_hex ~ '^[0-9A-F]{64}$'),
