  run_input_identity_id uuid, run_input_hash_hex text check (run_input_hash_hex is null or run_input_hash_hex ~ '^[0-9A-F]{64}$'), result_identity_id uuid, result_hash_hex text check (result_hash_hex is null or result_hash_hex ~ '^[0-9A-F]{64}$'), evidence_object_identity_id uuid, evidence_object_hash_hex text check (evidence_object_hash_hex is null or evidence_object_hash_hex ~ '^[0-9A-F]{64}$'),
  validation_protocol_identity_id uuid, validation_protocol_hash_hex text check (validation_protocol_hash_hex is null or validation_protocol_hash_hex ~ '^[0-9A-F]{64}$'), validation_result_identity_id uuid, validation_result_hash_hex text check (validation_result_hash_hex is null or validation_result_hash_hex ~ '^[0-9A-F]{64}$'),
  validation_assessment_protocol_identity_id uuid, validation_assessment_protocol_hash_hex text check (validation_assessment_protocol_hash_hex is null or validation_assessment_protocol_hash_hex ~ '^[0-9A-F]{64}$'), validation_assessment_result_identity_id uuid, validation_assessment_result_hash_hex text check (validation_assessment_result_hash_hex is null or validation_assessment_result_hash_hex ~ '^[0-9A-F]{64}$'),
  robustness_comparison_protocol_identity_id uuid, robustness_comparison_protocol_hash_hex text check (robustness_comparison_protocol_hash_hex is null or robustness_comparison_protocol_hash_hex ~ '^[0-9A-F]{64}$'), robustness_comparison_result_identity_id uuid, robustness_comparison_result_hash_hex text check (robustness_comparison_result_hash_hex is null or robustness_comparison_result_hash_hex ~ '^[0-9A-F]{64}$'),
  canonical_payload jsonb not null, created_at timestamptz not null default transaction_timestamp(),
  constraint research_scientific_promotion_transitions_membership_fk foreign key (tenant_membership_id, tenant_id, principal_id) references investing.tenant_memberships (tenant_membership_id, tenant_id, principal_id),
  constraint research_scientific_promotion_transitions_investigation_fk foreign key (research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context) references investing.research_investigations (research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context),
  constraint research_scientific_promotion_transitions_subject_experiment_fk foreign key (research_experiment_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, subject_experiment_hash_hex, subject_experiment_parameters_hash_hex, subject_research_ir_hash_hex) references investing.research_experiments (research_experiment_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, experiment_hash_hex, experiment_parameters_hash_hex, research_ir_hash_hex),
