  constraint research_scientific_promotion_transitions_result_fk foreign key (result_identity_id, run_input_identity_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, result_hash_hex) references investing.research_results_scientific_identities (result_identity_id, run_input_identity_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_transitions_evidence_object_fk foreign key (evidence_object_identity_id, run_input_identity_id, result_identity_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, evidence_object_hash_hex) references investing.research_evidence_objects_scientific_identities (evidence_identity_id, run_input_identity_id, result_identity_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_transitions_validation_protocol_fk foreign key (validation_protocol_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, validation_protocol_hash_hex) references investing.research_validation_protocols_scientific_identities (research_validation_protocol_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_transitions_validation_result_fk foreign key (validation_result_identity_id, validation_protocol_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, validation_result_hash_hex) references investing.research_validation_results_scientific_identities (research_validation_result_identity_id, research_validation_protocol_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
