  constraint research_scientific_promotion_transitions_validation_assessment_result_fk foreign key (validation_assessment_result_identity_id, validation_assessment_protocol_identity_id, validation_result_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, validation_assessment_result_hash_hex) references investing.research_validation_assessment_results_scientific_identities (research_validation_assessment_result_identity_id, research_validation_assessment_protocol_identity_id, research_validation_result_identity_id, research_investigation_id, research_experiment_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_transitions_robustness_protocol_fk foreign key (robustness_comparison_protocol_identity_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, robustness_comparison_protocol_hash_hex) references investing.research_experiment_comparison_protocols_scientific_identities (research_experiment_comparison_protocol_identity_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_transitions_robustness_result_fk foreign key (robustness_comparison_result_identity_id, robustness_comparison_protocol_identity_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, robustness_comparison_result_hash_hex) references investing.research_experiment_comparison_results_scientific_identities (research_experiment_comparison_result_identity_id, research_experiment_comparison_protocol_identity_id, research_investigation_id, tenant_id, principal_id, tenant_membership_id, operation_scope, source_context, hash_hex),
  constraint research_scientific_promotion_predecessor_pair_check check ((predecessor_transition_identity_id is null and predecessor_transition_hash_hex is null) or (predecessor_transition_identity_id is not null and predecessor_transition_hash_hex is not null)),
  constraint research_scientific_promotion_rejected_pair_check check ((rejected_transition_identity_id is null and rejected_transition_hash_hex is null) or (rejected_transition_identity_id is not null and rejected_transition_hash_hex is not null)),
  constraint research_scientific_promotion_supersedes_pair_check check ((supersedes_transition_identity_id is null and supersedes_transition_hash_hex is null) or (supersedes_transition_identity_id is not null and supersedes_transition_hash_hex is not null)),
  constraint research_scientific_promotion_successor_protocol_pair_check check ((superseded_by_successor_protocol_identity_id is null and superseded_by_successor_protocol_hash_hex is null) or (superseded_by_successor_protocol_identity_id is not null and superseded_by_successor_protocol_hash_hex is not null)),
  constraint research_scientific_promotion_successor_root_pair_check check ((superseded_by_successor_root_transition_identity_id is null and superseded_by_successor_root_transition_hash_hex is null) or (superseded_by_successor_root_transition_identity_id is not null and superseded_by_successor_root_transition_hash_hex is not null)),
  constraint research_scientific_promotion_state_graph_check check ((predecessor_state = 'DRAFT_RESEARCH' and resulting_state = 'EXECUTED') or (predecessor_state in ('EXECUTED','INSUFFICIENT_EVIDENCE','PROMOTION_ELIGIBLE','REJECTED') and resulting_state in ('INSUFFICIENT_EVIDENCE','VALIDATION_FAILED','VALIDATION_PASSED')) or (predecessor_state = 'VALIDATION_FAILED' and resulting_state = 'REJECTED') or (predecessor_state = 'VALIDATION_PASSED' and resulting_state = 'PROMOTION_ELIGIBLE') or (predecessor_state in ('EXECUTED','INSUFFICIENT_EVIDENCE','PROMOTION_ELIGIBLE','REJECTED') and resulting_state = 'SUPERSEDED')),
  constraint research_scientific_promotion_lifecycle_presence_check check (((predecessor_state = 'DRAFT_RESEARCH' and resulting_state = 'EXECUTED' and predecessor_transition_identity_id is null and rejected_transition_identity_id is null and supersedes_transition_identity_id is null and superseded_by_successor_protocol_identity_id is null and superseded_by_successor_root_transition_identity_id is null) or (predecessor_transition_identity_id is not null and predecessor_state <> 'DRAFT_RESEARCH' and resulting_state <> 'EXECUTED'))),
  constraint research_scientific_promotion_rejected_presence_check check ((resulting_state = 'REJECTED' and rejected_transition_identity_id is not null) or (resulting_state <> 'REJECTED' and rejected_transition_identity_id is null)),
  constraint research_scientific_promotion_superseded_presence_check check ((resulting_state = 'SUPERSEDED' and supersedes_transition_identity_id is not null and superseded_by_successor_protocol_identity_id is not null and superseded_by_successor_root_transition_identity_id is not null and superseded_by_successor_protocol_hash_hex <> protocol_hash_hex) or (resulting_state <> 'SUPERSEDED' and supersedes_transition_identity_id is null and superseded_by_successor_protocol_identity_id is null and superseded_by_successor_root_transition_identity_id is null)),
  constraint research_scientific_promotion_payload_check check (jsonb_typeof(canonical_payload) = 'object' and not investing.rl8c_jsonb_has_number_v1(canonical_payload) and canonical_payload->>'schemaVersion' = 'SCIENTIFIC_PROMOTION_TRANSITION_V1' and canonical_payload->>'predecessorState' = predecessor_state and canonical_payload->>'resultingState' = resulting_state and canonical_payload#>>'{protocol,hashHex}' = protocol_hash_hex and canonical_payload#>>'{subject,subjectExperiment,hashHex}' = subject_experiment_hash_hex and canonical_payload#>>'{subject,subjectExperimentParameters,hashHex}' = subject_experiment_parameters_hash_hex and canonical_payload#>>'{subject,subjectResearchIr,hashHex}' = subject_research_ir_hash_hex and investing.rl8c_sha256_hex_v1(transition_hash_domain, canonical_payload) = transition_hash_hex),
  constraint research_scientific_promotion_transitions_rl8c_lifecycle_key unique (research_scientific_promotion_transition_identity_id, tenant_id, research_investigation_id, research_scientific_promotion_protocol_identity_id, subject_experiment_hash_hex, subject_experiment_parameters_hash_hex, subject_research_ir_hash_hex, transition_hash_hex),
  constraint research_scientific_promotion_transitions_rl8c_cross_chain_target_key unique (research_scientific_promotion_transition_identity_id, tenant_id, research_investigation_id, research_scientific_promotion_protocol_identity_id, protocol_hash_hex, subject_experiment_hash_hex, subject_experiment_parameters_hash_hex, subject_research_ir_hash_hex, transition_hash_hex),
  constraint research_scientific_promotion_transition_hash_key unique (transition_hash_algorithm, transition_hash_domain, transition_hash_version, transition_hash_hex)
