  select count(*) into v_writer_count from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'investing' and p.proname like 'persist_research_scientific_promotion%';
  if v_writer_count <> 0 then raise exception 'RL-8C1 postcondition failed: RL-8 writer SECURITY DEFINER surface must be zero in C1'; end if;
